import{_ as a,a as s,a3 as t,o}from"./chunks/framework.yJBLK5ap.js";const m=JSON.parse('{"title":"Split Dali Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"helm/hpcc/docs/dali-split.md","filePath":"helm/hpcc/docs/dali-split.md","lastUpdated":1795797312000}'),l={name:"helm/hpcc/docs/dali-split.md"};function i(n,e,r,c,d,p){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="split-dali-deployment" tabindex="-1">Split Dali Deployment <a class="header-anchor" href="#split-dali-deployment" aria-label="Permalink to &quot;Split Dali Deployment&quot;">​</a></h1><p>Split a deployment across two Helm releases when Dali and the application stack need separate ownership:</p><ul><li>The Dali release defines an enabled <code>dali[]</code> entry and owns the Dali StatefulSet.</li><li>The application release sets <code>dali: []</code>, runs the remaining components, and connects to the Dali release through <code>global.externalDaliSvc</code>.</li></ul><p>Set <code>global.externalDaliSvc</code> only in the application release&#39;s values. It takes a <code>host:port</code> endpoint; a component-level <code>externalDaliSvc</code> can override it. The Dali release retains its local Dali configuration and does not use this setting.</p><h2 id="shared-resources" tabindex="-1">Shared Resources <a class="header-anchor" href="#shared-resources" aria-label="Permalink to &quot;Shared Resources&quot;">​</a></h2><p>The Dali-owning release (the one with an enabled dali[] entry) renders the namespace-wide base NetworkPolicies and shared ServiceAccounts/Roles/RoleBindings, including policies that enforce namespace-wide egress settings. Configure those settings only on the Dali release. The application release omits the shared resources and creates policies for its active components.</p><p>NetworkPolicies in this pattern use namespace-scoped pod selectors. A cross-namespace deployment therefore needs additional Dali ingress and client egress policies. For Prometheus scraping, configure metrics on each release whose pods should be labeled. Configure a Prometheus sink with <code>settings.autodiscovery: true</code> on the Dali-owning release to generate the shared scrape policy, and use the same scrape port across releases.</p><p>For values files, deployment commands, and end-to-end validation, see the <a href="./../../examples/dali-split-same-namespace/README.html">same-namespace split Dali example</a>.</p>',8)])])}const u=a(l,[["render",i]]);export{m as __pageData,u as default};
